patch:
diff --git a/tests/repro/no-unused-expressions-use-strict.js b/tests/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..91811d9
--- /dev/null
+++ b/tests/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,21 @@
+"use strict";
+// Reproduction for: no-unused-expressions reports 'use strict' in 9.25.0
+const path = require("node:path");
+const { Linter } = require(path.resolve(__dirname, "../../lib/api"));
+const espree = require("espree");
+
+const code = "'use strict';\nfunction f() {\n  'use strict';\n  return 1;\n}\nf();\n";
+const linter = new Linter();
+console.log("ESLint", Linter.version);
+let failed = false;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const messages = linter.verify(code, {
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	});
+	const ast = espree.parse(code, { ecmaVersion: ecmaVersion === "latest" ? "latest" : ecmaVersion, range: true });
+	console.log(`ecmaVersion ${ecmaVersion}: Program.body[0].directive = ${JSON.stringify(ast.body[0].directive)}; ${messages.length} message(s)`);
+	for (const m of messages) console.log(`  ${m.line}:${m.column} ${m.ruleId} ${m.message}`);
+	if (messages.length) failed = true;
+}
+process.exitCode = failed ? 1 : 0;
